[meta]
name = Herran's Castle
ambient = 0.42 0.4 0.48
fog = 0.12 0.12 0.16
fog_range = 10 60
model_range = 40
indoor_range = 18
sky = storm
torch = 6 1.0 0.72 0.45
start = 16 38 -90
default = _
entity_floor = auto
roofs = true
edge_top = -40
edge_tex = herran_ashlar

// Herran's Castle, high over a sea of cloud under a stormy night: the seat of Herran, a son of Lyra the
// Embracer, who kept the fifth seal, the Auric Sigil, the one the king never held. His sister Ilvane
// bent hers to the moon; he bent his to his own flesh. He wanted his mother's many hands, and grafted
// arms onto his drakes, and then onto himself. You come up the stair of light from Lyra's altar in
// Vesperholm onto the Cloud Quay, where the shrine stands, and through the gatehouse into the Ring: a
// narrow passage of sooted brick round a void that falls to the clouds, arches open on the drop. Four
// towers stand on it: the Laboratory (NW), with the Spire Key, and behind a false wall in its back wall
// the secret lab; the Clock Tower (SW), whose stair winds up inside its walls to 10 m and out onto the
// High Walk over the void; the Aviary (SE), its drakes and its gallery; and the Belvedere (NE), where
// the High Walk ends, its cage lift down to the Ring the short way home, and the door the Spire Key
// opens on the passage into the foot of Herran's Spire.

[legend]
// The sea of cloud far below: a sheer fall that no one lives through.
_ = floor tex=cloud_sea h=-40 side=herran_ashlar chasm fall=cloud void
// The castle's sooted brick: the Ring's walls, the towers, the spire; the quay's balustrade, and the
// low walls of the Ring's arches onto the void.
# = wall tex=herran_brick top=9 cap=herran_slate
% = wall tex=herran_brick top=16 cap=herran_slate
& = wall tex=herran_brick top=24 cap=herran_slate
b = wall tex=herran_ashlar top=1.1 cap=herran_ashlar
c = wall tex=herran_brick top=2.1 cap=herran_slate
// The Cloud Quay, and the gatehouse's passage half a metre up.
, = floor tex=herran_ashlar h=0 side=herran_ashlar
p = floor tex=encaustic_tile h=0.5 ceil=5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
// The Ring, a metre up, round the void.
r = floor tex=encaustic_tile h=1 ceil=4.5 ceil_tex=herran_ashlar side=herran_brick roof=9 dark=0.3
// The Laboratory, and the secret lab behind its false wall, darker still.
l = floor tex=lab_tile h=1 ceil=4.5 ceil_tex=lab_tile side=lab_tile roof=16 dark=0.25
s = floor tex=lab_tile h=1 ceil=4 ceil_tex=lab_tile side=lab_tile roof=16 dark=0.65
// The Clock Tower's stair, half a metre a tile inside its walls, and its top room at 10 m.
1 = floor tex=encaustic_tile h=1.5 ceil=6 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
2 = floor tex=encaustic_tile h=2 ceil=6.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
3 = floor tex=encaustic_tile h=2.5 ceil=7 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
4 = floor tex=encaustic_tile h=3 ceil=7.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
5 = floor tex=encaustic_tile h=3.5 ceil=8 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
6 = floor tex=encaustic_tile h=4 ceil=8.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
7 = floor tex=encaustic_tile h=4.5 ceil=9 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
8 = floor tex=encaustic_tile h=5 ceil=9.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
9 = floor tex=encaustic_tile h=5.5 ceil=10 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
i = floor tex=encaustic_tile h=6 ceil=10.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
α = floor tex=encaustic_tile h=6.5 ceil=11 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
β = floor tex=encaustic_tile h=7 ceil=11.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
γ = floor tex=encaustic_tile h=7.5 ceil=12 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
δ = floor tex=encaustic_tile h=8 ceil=12.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
ε = floor tex=encaustic_tile h=8.5 ceil=13 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
ζ = floor tex=encaustic_tile h=9 ceil=13.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
η = floor tex=encaustic_tile h=9.5 ceil=14 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
j = floor tex=encaustic_tile h=10 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.25
// The Aviary, open to the sky, and the stair up its wall to its gallery at 4 m.
a = floor tex=herran_ashlar h=1 side=herran_brick
t = floor tex=herran_ashlar h=1.5 side=herran_brick
u = floor tex=herran_ashlar h=2 side=herran_brick
v = floor tex=herran_ashlar h=2.5 side=herran_brick
w = floor tex=herran_ashlar h=3 side=herran_brick
x = floor tex=herran_ashlar h=3.5 side=herran_brick
y = floor tex=herran_ashlar h=4 side=herran_brick
// The Belvedere's top room at 10 m, and its lift's shaft, down to the Ring.
m = floor tex=encaustic_tile h=10 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
e = floor tex=iron_grating h=1 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 chasm
// The High Walk's iron deck over the void, 10 m up.
h = floor tex=iron_grating h=10 side=herran_ashlar
// The passage into the foot of the Spire.
q = floor tex=encaustic_tile h=10 ceil=15 ceil_tex=herran_ashlar side=herran_brick roof=24 dark=0.3

