[entities]
// The stair of light down to Lyra's altar in Vesperholm, at the quay's south edge, and the shrine.
A = exit map=vesperholm at=34,18,180 label=Descend_to_Vesperholm model=sky_stair way=out yaw=90
B = save_statue
// The false wall in the Laboratory's back wall, onto the secret lab.
W = secret_wall
// The Belvedere's lift down to the Ring: fastened until its first ride down.
L = lift top=10 start=top locked model=cage on=e
// Finds: the Spire Key in the Laboratory, the secret lab's three, and the Aviary's gallery.
K = chest item=spire_key gold=120 model=banded
D = chest item=graft_draught count=2 gold=140 model=coffer
E = chest item=herran_bonesaw gold=150 model=banded
F = chest item=sun_tincture count=2 gold=160 model=coffer
G = chest item=bitter_root count=2 gold=110
// The door to the Spire's passage, and the way in at its end.
H = door key=spire_key
J = exit map=herran_spire at=5,25,-90 label=Climb_the_Spire model=spire_door yaw=0 boss=herran_dead
// Gaslight on the quay and in the Belvedere, and the gas jets along the Ring.
M = gas_lamp
Ç = light y=2.6 color=1.0,0.72,0.45 radius=6
// The laboratories' dressing: specimen jars, alembic benches, vats, the operating tables and shelves.
O = specimen_jar
P = alembic_bench
Q = vat
R = surgery_table
S = potion_shelf
// The skyline: the gatehouse's twin towers and the Laboratory's, octagonal; the Clock Tower; the
// Belvedere's loggia; the round Aviary; the Spire's needle.
T = herran_tower style=octagon height=12 on=%
U = herran_tower style=clock height=16 on=%
V = herran_tower style=belvedere height=12 on=%
X = herran_tower style=needle height=34 on=&
Y = herran_tower style=round height=14 on=%
// Herran's creatures: Drake Magi in the towers, Grafted Drakes on the wing, Vat Spawn in the labs.
Ä = drake_magus
Å = grafted_drake
Æ = vat_spawn
// Herran's ledger in the Laboratory, and his journal: a page in the secret lab, and one atop each of
// the Clock Tower and the Belvedere.
À = hint text="A ledger of drakes, each with arms sewn on.|The last entries are in a shakier hand."
Á = hint text="Mother holds out six hands. I have two.|The drakes take the grafts well. Next, mine."
Â = hint text="Ilvane wed the moon on her seal to keep her city.|I shall wed the sun's to my own flesh."
Ã = hint text="My sister and I were born of the Embracer.|Neither she nor Mother answers me now."
